package cli

import (
	"bytes"
	"context"
	"fmt"
	"os"
	"strings"

	"github.com/charmbracelet/bubbles/spinner"
	"github.com/charmbracelet/bubbles/viewport"
	tea "github.com/charmbracelet/bubbletea"
	"github.com/charmbracelet/lipgloss"
	"github.com/entireio/cli/cmd/entire/cli/api"
)

// activityDataMsg is sent when API data has been fetched.
type activityDataMsg struct {
	stats  contributionStats
	repos  []repoContribution
	hourly []hourlyPoint
	days   []commitDay
}

// activityErrMsg is sent when fetching fails.
type activityErrMsg struct{ err error }

type activityModel struct {
	// Data (nil until loaded)
	stats  *contributionStats
	repos  []repoContribution
	hourly []hourlyPoint
	days   []commitDay

	// Loading state
	loading bool
	loadErr error
	spinner spinner.Model

	// Fetch context
	ctx    context.Context
	client *api.Client

	// View state
	viewport viewport.Model
	sty      activityStyles
	useColor bool
	width    int
	height   int
	ready    bool
}

func runActivityTUI(ctx context.Context, client *api.Client) error {
	sp := spinner.New()
	sp.Spinner = spinner.Dot
	sp.Style = lipgloss.NewStyle().Foreground(lipgloss.Color("8"))

	m := activityModel{
		loading:  true,
		spinner:  sp,
		ctx:      ctx,
		client:   client,
		useColor: shouldUseColor(os.Stdout),
	}
	p := tea.NewProgram(m, tea.WithAltScreen())
	if _, err := p.Run(); err != nil {
		return fmt.Errorf("activity TUI: %w", err)
	}
	return nil
}

func (m activityModel) fetchData() tea.Msg { //nolint:ireturn // bubbletea Cmd signature requires tea.Msg return
	activity, commits, err := fetchActivityData(m.ctx, m.client)
	if err != nil {
		return activityErrMsg{err: err}
	}

	return activityDataMsg{
		stats: contributionStats{
			Tasks:         activity.Stats.Tasks,
			Throughput:    activity.Stats.Throughput,
			Iteration:     activity.Stats.Iteration,
			ContinuityH:   activity.Stats.ContinuityHours,
			Streak:        activity.Stats.LifetimeStreak,
			CurrentStreak: activity.Stats.LifetimeCurrentStreak,
		},
		repos:  activity.Repos,
		hourly: activity.HourlyContributions,
		days:   groupCommitsByDay(commits),
	}
}

func (m activityModel) Init() tea.Cmd {
	return tea.Batch(m.spinner.Tick, m.fetchData)
}

func (m activityModel) Update(msg tea.Msg) (tea.Model, tea.Cmd) { //nolint:ireturn // bubbletea interface
	switch msg := msg.(type) {
	case activityDataMsg:
		m.loading = false
		m.stats = &msg.stats
		m.repos = msg.repos
		m.hourly = msg.hourly
		m.days = msg.days
		if m.width > 0 {
			m = m.withViewport()
		}
		return m, nil

	case activityErrMsg:
		m.loading = false
		m.loadErr = msg.err
		return m, nil

	case tea.KeyMsg:
		if msg.Type == tea.KeyEscape || msg.Type == tea.KeyCtrlC || msg.String() == "q" {
			return m, tea.Quit
		}

	case tea.WindowSizeMsg:
		m.width = msg.Width
		m.height = msg.Height
		m.sty = newActivityStylesWithWidth(m.width, m.useColor)
		if m.stats != nil {
			m = m.withViewport()
		}
		return m, nil

	case spinner.TickMsg:
		if m.loading {
			var cmd tea.Cmd
			m.spinner, cmd = m.spinner.Update(msg)
			return m, cmd
		}
	}

	if m.ready {
		var cmd tea.Cmd
		m.viewport, cmd = m.viewport.Update(msg)
		return m, cmd
	}

	return m, nil
}

func (m activityModel) withViewport() activityModel {
	headerHeight := m.headerLineCount()
	vpHeight := m.height - headerHeight - 1
	if vpHeight < 1 {
		vpHeight = 1
	}

	if !m.ready {
		m.viewport = viewport.New(m.width, vpHeight)
		m.ready = true
	} else {
		m.viewport.Width = m.width
		m.viewport.Height = vpHeight
	}
	m.viewport.SetContent(m.renderCommits())
	return m
}

func (m activityModel) View() string {
	if m.loadErr != nil {
		return fmt.Sprintf("\n  Failed to load activity: %s\n\n  Press q to quit.\n", m.loadErr)
	}

	if m.loading {
		return fmt.Sprintf("\n  %s Loading activity...\n", m.spinner.View())
	}

	if !m.ready {
		return ""
	}

	var b strings.Builder
	b.WriteString(m.renderHeader())
	b.WriteString(m.viewport.View())
	b.WriteString("\n")
	b.WriteString(m.renderFooter())
	return b.String()
}

func (m activityModel) renderHeader() string {
	if m.stats == nil {
		return ""
	}
	var buf bytes.Buffer
	buf.WriteString("\n")
	renderStatCards(&buf, m.sty, *m.stats)
	buf.WriteString("\n")
	renderContributionChart(&buf, m.sty, m.hourly, m.repos)
	buf.WriteString("\n")
	renderRepoChart(&buf, m.sty, m.repos)
	buf.WriteString("\n")
	return buf.String()
}

func (m activityModel) headerLineCount() int {
	return strings.Count(m.renderHeader(), "\n")
}

func (m activityModel) renderCommits() string {
	var buf bytes.Buffer
	renderCommitListN(&buf, m.sty, m.days, -1)
	return buf.String()
}

func (m activityModel) renderFooter() string {
	if !m.sty.colorEnabled {
		return ""
	}
	helpStyle := lipgloss.NewStyle().Foreground(lipgloss.Color("241"))
	keyStyle := lipgloss.NewStyle().Foreground(lipgloss.Color("245")).Bold(true)
	sep := helpStyle.Render(" · ")

	scrollPct := ""
	if m.viewport.TotalLineCount() > m.viewport.Height {
		pct := int(m.viewport.ScrollPercent() * 100)
		scrollPct = sep + helpStyle.Render(strings.Repeat(" ", max(0, m.width-40))+padLeft(pct)+"%")
	}

	return keyStyle.Render("↑↓") + helpStyle.Render(" scroll") +
		sep + keyStyle.Render("q") + helpStyle.Render(" quit") +
		scrollPct
}

func newActivityStylesWithWidth(width int, useColor bool) activityStyles {
	return activityStyles{
		colorEnabled: useColor,
		width:        width,
		bold:         lipgloss.NewStyle().Bold(true),
		dim:          lipgloss.NewStyle().Faint(true),
		label:        lipgloss.NewStyle().Foreground(lipgloss.Color("8")).Bold(true),
		value:        lipgloss.NewStyle().Bold(true),
		unit:         lipgloss.NewStyle().Foreground(lipgloss.Color("8")),
		desc:         lipgloss.NewStyle().Foreground(lipgloss.Color("8")),
		repoNm:       lipgloss.NewStyle().Foreground(lipgloss.Color("7")),
		commitH:      lipgloss.NewStyle().Foreground(lipgloss.Color("8")),
		commitM:      lipgloss.NewStyle().Bold(true),
		add:          lipgloss.NewStyle().Foreground(lipgloss.Color("2")),
		del:          lipgloss.NewStyle().Foreground(lipgloss.Color("1")),
		muted:        lipgloss.NewStyle().Foreground(lipgloss.Color("8")),
	}
}

func padLeft(n int) string {
	s := strings.Builder{}
	if n < 10 {
		s.WriteString("  ")
	} else if n < 100 {
		s.WriteString(" ")
	}
	fmt.Fprintf(&s, "%d", n)
	return s.String()
}

package cli

import (
	"context"
	"fmt"
	"io"
	"strings"
	"time"

	"github.com/charmbracelet/bubbles/cursor"
	"github.com/charmbracelet/bubbles/textinput"
	"github.com/charmbracelet/bubbles/viewport"
	tea "github.com/charmbracelet/bubbletea"
	"github.com/charmbracelet/lipgloss"
	"github.com/entireio/cli/cmd/entire/cli/search"
	"github.com/entireio/cli/cmd/entire/cli/stringutil"
)

// searchMode tracks whether the user is browsing results or editing the search bar.
type searchMode int

const (
	modeBrowse searchMode = iota
	modeSearch
	modeDetail
)

// searchResultsMsg is sent when a search API call completes.
type searchResultsMsg struct {
	results []search.Result
	total   int
	err     error
}

// searchMoreResultsMsg is sent when a fetch-more-results call completes.
type searchMoreResultsMsg struct {
	results []search.Result
	err     error
}

// searchStyles holds lipgloss styles specific to the search TUI.
// Styles shared with the status TUI (bold, dim, green, red, cyan, agent/id)
// are accessed via the embedded statusStyles.
type searchStyles struct {
	statusStyles

	sectionTitle lipgloss.Style // bold uppercase section headers
	label        lipgloss.Style // dim key labels in detail panel
	selected     lipgloss.Style // highlighted selected row
	helpKey      lipgloss.Style // colored key hints in footer
	helpSep      lipgloss.Style // dim separator dots in footer
	detailTitle  lipgloss.Style // colored title and section headers (orange, bold)
	detailBorder lipgloss.Style // border style for detail card
}

func newSearchStyles(ss statusStyles) searchStyles {
	s := searchStyles{statusStyles: ss}
	if !ss.colorEnabled {
		return s
	}
	s.sectionTitle = lipgloss.NewStyle().Bold(true).Foreground(lipgloss.Color("244"))
	s.label = lipgloss.NewStyle().Foreground(lipgloss.Color("244"))
	s.selected = lipgloss.NewStyle().Foreground(lipgloss.Color("214")).Bold(true)
	s.helpKey = lipgloss.NewStyle().Foreground(lipgloss.Color("245"))
	s.helpSep = lipgloss.NewStyle().Foreground(lipgloss.Color("240"))
	s.detailTitle = lipgloss.NewStyle().Foreground(lipgloss.Color("214")).Bold(true)
	s.detailBorder = lipgloss.NewStyle().
		Border(lipgloss.RoundedBorder()).
		BorderForeground(lipgloss.Color("243")).
		Padding(1, 2)
	return s
}

const resultsPerPage = 25

// searchModel is the bubbletea model for interactive search results.
type searchModel struct {
	results      []search.Result
	cursor       int
	page         int // 0-based display page index
	total        int
	width        int
	height       int
	mode         searchMode
	loading      bool
	fetchingMore bool // true while fetching next API page
	searchErr    string
	input        textinput.Model
	searchCfg    search.Config
	apiPage      int // 1-based last-fetched API page
	styles       searchStyles
	detailVP     viewport.Model // full-screen detail view
	browseVP     viewport.Model // scrollable browse view
}

// pageResults returns the slice of results for the current page.
func (m searchModel) pageResults() []search.Result {
	start := m.page * resultsPerPage
	if start >= len(m.results) {
		return nil
	}
	end := start + resultsPerPage
	if end > len(m.results) {
		end = len(m.results)
	}
	return m.results[start:end]
}

// totalPages returns the number of pages based on the API's total result count.
func (m searchModel) totalPages() int {
	if m.total == 0 {
		return 1
	}
	return (m.total + resultsPerPage - 1) / resultsPerPage
}

// selectedResult returns the currently selected result, accounting for pagination.
func (m searchModel) selectedResult() *search.Result {
	pageResults := m.pageResults()
	if m.cursor >= 0 && m.cursor < len(pageResults) {
		return &pageResults[m.cursor]
	}
	return nil
}

func newSearchModel(results []search.Result, query string, total int, cfg search.Config, ss statusStyles) searchModel {
	styles := newSearchStyles(ss)

	ti := textinput.New()
	ti.SetValue(query)
	ti.Prompt = " › "
	ti.Placeholder = "search checkpoints... (author:name date:week branch:main repo:owner/name or repo:*)"
	ti.CharLimit = 200
	ti.Width = max(ss.width-6, 30)
	if ss.colorEnabled {
		ti.PromptStyle = lipgloss.NewStyle().Foreground(lipgloss.Color("214")).Bold(true)
		ti.TextStyle = lipgloss.NewStyle()
		ti.PlaceholderStyle = lipgloss.NewStyle().Foreground(lipgloss.Color("241"))
		ti.Cursor.Style = lipgloss.NewStyle().Foreground(lipgloss.Color("214"))
	}

	var apiPage int
	if results != nil {
		apiPage = 1
	}

	m := searchModel{
		results:   results,
		total:     total,
		width:     ss.width,
		mode:      modeBrowse,
		input:     ti,
		searchCfg: cfg,
		apiPage:   apiPage,
		styles:    styles,
		browseVP:  viewport.New(ss.width, 1), // height set on first WindowSizeMsg
	}
	m = m.refreshBrowseContent()
	return m
}

func (m searchModel) Init() tea.Cmd {
	if m.mode == modeSearch {
		return textinput.Blink
	}
	return nil
}

func (m searchModel) Update(msg tea.Msg) (tea.Model, tea.Cmd) { //nolint:ireturn,cyclop // bubbletea interface
	switch msg := msg.(type) {
	case searchResultsMsg:
		m.loading = false
		m.fetchingMore = false
		if msg.err != nil {
			m.searchErr = msg.err.Error()
			m = m.refreshBrowseContent()
			return m, nil
		}
		m.searchErr = ""
		m.results = msg.results
		m.total = msg.total
		m.apiPage = 1
		m.cursor = 0
		m.page = 0
		m.browseVP.GotoTop()
		m = m.refreshBrowseContent()
		return m, nil

	case searchMoreResultsMsg:
		m.fetchingMore = false
		if msg.err != nil {
			m.searchErr = msg.err.Error()
			m = m.refreshBrowseContent()
			return m, nil
		}
		m.apiPage++
		if len(msg.results) > 0 {
			m.results = append(m.results, msg.results...)
		} else {
			// API returned no more results — cap total to what we have
			m.total = len(m.results)
		}
		m = m.refreshBrowseContent()
		return m, nil

	case tea.WindowSizeMsg:
		m.width = msg.Width
		m.height = msg.Height
		m.input.Width = max(msg.Width-6, 30)
		m.browseVP.Width = msg.Width
		m.browseVP.Height = max(msg.Height-1, 1) // reserve 1 line for footer
		if m.mode == modeDetail {
			m.detailVP.Width = msg.Width
			m.detailVP.Height = max(msg.Height-2, 1)
		}
		m = m.refreshBrowseContent()
		return m, nil

	case tea.KeyMsg:
		switch m.mode {
		case modeSearch:
			return m.updateSearchMode(msg)
		case modeDetail:
			return m.updateDetailMode(msg)
		case modeBrowse:
			return m.updateBrowseMode(msg)
		}
	}
	return m, nil
}

func (m searchModel) updateSearchMode(msg tea.KeyMsg) (tea.Model, tea.Cmd) { //nolint:ireturn // bubbletea pattern
	switch msg.String() {
	case "esc":
		m.mode = modeBrowse
		m.input.Blur()
		m = m.refreshBrowseContent()
		return m, nil
	case "enter":
		raw := strings.TrimSpace(m.input.Value())
		if raw == "" {
			return m, nil
		}
		parsed := search.ParseSearchInput(raw)
		if err := search.ValidateRepoFilters(parsed.Repos); err != nil {
			m.searchErr = err.Error()
			m = m.refreshBrowseContent()
			return m, nil
		}
		m.mode = modeBrowse
		m.input.Blur()
		m.loading = true
		m.searchErr = ""
		cfg := m.searchCfg
		cfg.Query = parsed.Query
		if cfg.Query == "" {
			cfg.Query = search.WildcardQuery
		}
		cfg.Author = parsed.Author
		cfg.Date = parsed.Date
		cfg.Branch = parsed.Branch
		cfg.Repos = parsed.Repos
		m.searchCfg = cfg
		m = m.refreshBrowseContent()
		return m, performSearch(cfg)
	}

	var cmd tea.Cmd
	m.input, cmd = m.input.Update(msg)
	return m, cmd
}

